export const privacyHtml = "<div class=\"conInner guidInfoWrap\">\r\n    <div class=\"centerBox\">\r\n        <div class=\"messageBox\">\r\n            <p>K-water 물문화관 통합 포털은 「개인정보 보호법」 (이하 '보호법'이라 한다) 제30조에 따라 정보주체의 개인정보보호 및 권익을 보호하고 개인정보와 관련한 이용자의 고충을 원활하게 처리할 수 있도록 다음과 같은 개인정보 처리지침을 수립 및 공개 하고 있습니다.</p>\r\n        </div>\r\n\r\n        <div class=\"down_01 top-action-buttons\">\r\n            <strong>\r\n                <a href=\"https://www.law.go.kr/LSW/lsInfoP.do?lsId=011357&ancYnChk=0#0000\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n                    ‘개인정보보호법’ 바로가기\r\n                    <span class=\"hidden\">다운로드</span>\r\n                </a>\r\n                <a href=\"https://www.riverguide.go.kr/template/guid_info_202609.pdf\" download=\"개인정보처리방침(신구대비표)PDF다운로드.pdf\"  title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n                    개인정보처리방침(신구대비표)PDF다운로드\r\n                    <span class=\"hidden\">다운로드</span>\r\n                </a>\r\n            </strong>\r\n        </div>\r\n\r\n        <div class=\"guid_infoLabel\">\r\n            <strong class=\"lb_title\">주요 개인정보 처리 표시(라벨링)</strong>\r\n            <div class=\"label_info\">\r\n                <p class=\"img label01\" title=\"개인정보수집\"></p>\r\n                <dl>\r\n                    <dt>개인정보 수집</dt>\r\n                    <dd>- 필수항목을 최소화하여 수집</dd>\r\n                    <dd>- 정보주체 동의하에 수집</dd>\r\n                    <dd>※ 세부사항은 개인정보 처리방침 본문 확인</dd>\r\n                </dl>\r\n            </div>\r\n            <div class=\"label_info\">\r\n                <p class=\"img label02\" title=\"개인정보 처리목적\"></p>\r\n                <dl>\r\n                    <dt>개인정보 처리목적</dt>\r\n                    <dd>- 대국민 서비스 제공</dd>\r\n                    <dd>- 민원처리 및 소관업무 수행 목적</dd>\r\n                    <dd>※ 세부사항은 개인정보 처리방침 본문 확인</dd>\r\n                </dl>\r\n            </div>\r\n            <div class=\"label_info\">\r\n                <p class=\"img label03\" title=\"보유기간 및 파기\"></p>\r\n                <dl>\r\n                    <dt>보유기간 및 파기</dt>\r\n                    <dd>- 회원정보는 탈퇴 시 파기</dd>\r\n                    <dd>- 관련 법령에 따라 보관 후 파기</dd>\r\n                    <dd>※ 세부사항은 개인정보 처리방침 본문 확인</dd>\r\n                </dl>\r\n            </div>\r\n            <div class=\"label_info\">\r\n                <p class=\"img label04\" title=\"개인정보 처리위탁\"></p>\r\n                <dl>\r\n                    <dt>개인정보 처리위탁</dt>\r\n                    <dd>- 개인정보처리시스템 운영위탁</dd>\r\n                    <dd>- 일부 소관업무 위탁</dd>\r\n                    <dd>※ 세부사항은 개인정보 처리방침 본문확인</dd>\r\n                </dl>\r\n            </div>\r\n            <div class=\"label_info\">\r\n                <p class=\"img label06\" title=\"개인정보 고충처리부서\"></p>\r\n                <dl>\r\n                    <dt>개인정보 고충처리부서</dt>\r\n                    <dd>- 정보보안처 박종웅</dd>\r\n                    <dd>- 042-629-3097</dd>\r\n                    <dd>- pju@kwater.or.kr</dd>\r\n                </dl>\r\n            </div>\r\n            <div class=\"label_info\">\r\n                <p class=\"img label07\" title=\"개인정보 수준진단\"></p>\r\n                <dl>\r\n                    <dt>개인정보 보호수준 평가</dt>\r\n                    <dd>- 2025년 개인정보</dd>\r\n                    <dd>보호수준 평가</dd>\r\n                    <dd>'S등급'</dd>\r\n                </dl>\r\n            </div>\r\n        </div>\r\n\r\n        <div id=\"textCenter\">\r\n            <ol>\r\n                <li>K-water 물문화관 통합 포털의 개인정보 처리방침은 다음과 같은 내용으로 구성되어 있습니다.</li>\r\n                <li>※ 목차의 조항 클릭 시 해당 조항으로 이동합니다.</li>\r\n            </ol>\r\n        </div>\r\n\r\n        <div class=\"guid_infoList\">\r\n            <ul>\r\n                <li>\r\n                    <a href=\"#step01\" class=\"new ico1_new_202509\">\r\n                        <span>제1조(개인정보파일 현황 및 개인정보의 처리목적)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step02\" class=\"ico2_new_202509\">\r\n                        <span>제2조(개인정보의 처리 및 보유기간)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step03\" class=\"new ico3_new_202509\">\r\n                        <span>제3조(처리하는 개인정보 항목)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step04\" class=\"new ico4_new_202509\">\r\n                        <span>제4조(만14세 미만 아동의 개인정보 처리)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step05\" class=\"ico5_new_202509\">\r\n                        <span>제5조(개인정보의 제3자 제공)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step06\" class=\"new ico6_new_202509\">\r\n                        <span>제6조(개인정보처리의 위탁)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step07\" class=\"new ico7_new_202509\">\r\n                        <span>제7조(정보주체와 법정대리인의 권리·의무)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step08\" class=\"ico8_new_202509\">\r\n                        <span>제8조(개인정보 파기절차 및 방법)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step09\" class=\"ico9_new_202509\">\r\n                        <span>제9조(개인정보의 안전성 확보 조치)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step10\" class=\"ico10_new_202509\">\r\n                        <span>제10조(개인정보 자동 수집 장치의 설치·운영 및 거부에 관한 사항)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step11\" class=\"new ico11_new_202509\">\r\n                        <span>제11조(민감정보의 공개 가능성 및 비공개 선택)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step12\" class=\"ico12_new_202509\">\r\n                        <span>제12조(개인정보 보호책임자 및 담당자)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step13\" class=\"new ico13_new_202509\">\r\n                        <span>제13조(개인정보를 열람청구를 접수처리하는 부서)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step14\" class=\"ico14_new_202509\">\r\n                        <span>제14조(권익침해 구제방법)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step15\" class=\"new ico15_new_202509\">\r\n                        <span>제15조(개인정보 보호수준 평가 결과)</span>\r\n                    </a>\r\n                </li>\r\n                <li>\r\n                    <a href=\"#step16\" class=\"new ico16_new_202509\">\r\n                        <span>제16조(개인정보 처리방침 변경)</span>\r\n                    </a>\r\n                </li>\r\n            </ul>\r\n        </div>\r\n    </div>\r\n\r\n</div>\r\n<ul class=\"policy_list\">\r\n    <div id=\"step01\">\r\n        <span class=\"hidden\">제1조(개인정보파일 현황 및 개인정보의 처리목적)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제1조(개인정보파일 현황 및 개인정보의 처리목적)</strong>\r\n        <ol>\r\n            <li>① K-water 물문화관 통합 포털은 다음의 목적을 위하여 최소한의 개인정보를 수집하여 처리합니다. 처리하고 있는 개인정보는 다음 목적 이외의 용도로는 이용되지 않으며, 이용 목적이 변경되는 경우에는 보호법 제18조에 따라 별도의 동의를 받는 등 필요한 조치를 이행할 예정입니다.\r\n            </li>\r\n            <div class=\"scrollTable\">\r\n            <table class=\"basic_board_table\">\r\n                <caption>개인정보 보호법에 따른 처리하는 목적을 보여주는 표입니다.</caption>\r\n                <colgroup>\r\n                    <col style=\"width: 8%;\">\r\n                    <col style=\"width: 46%;\">\r\n                    <col style=\"width: 46%;\">\r\n                </colgroup>\r\n                <thead>\r\n                    <tr>\r\n                        <th scope=\"col\">순번</th>\r\n                        <th scope=\"col\">개인정보파일의 명칭</th>\r\n                        <th scope=\"col\">처리목적</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <th scope=\"row\">1</th>\r\n                        <td>K-water 물문화관 통합 포털 자전거 종주인증 신청정보</td>\r\n                        <td>\r\n                            <ul>\r\n                                <li>자전거 종주인증 내역관리</li>\r\n                            </ul>\r\n                        </td>\r\n                    </tr>\r\n                    <tr>\r\n                        <th scope=\"row\">2</th>\r\n                        <td>K-water 물문화관 통합 포털 종주인증 수첩 및 기념품 구매정보</td>\r\n                        <td>\r\n                            <ul>\r\n                                <li>종주 인증 수첩 및 기념품(메달, 케이스, 인증서 등) 제작 및 배송</li>\r\n                            </ul>\r\n                        </td>\r\n                    </tr>\r\n                    <tr>\r\n                        <th scope=\"row\">3</th>\r\n                        <td>K-water 물문화관 통합 포털 회원정보</td>\r\n                        <td>\r\n                            <ul>\r\n                                <li>4대강 주변 시설 예약 및 자전거 종주인증 관리</li>\r\n                            </ul>\r\n                        </td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n            </div>\r\n            <li>\r\n                ② K-water 물문화관 통합 포털에서 처리하는 모든 개인정보파일에 대한 내용은 개인정보보호위원회 개인정보포털에서 확인할 수 있습니다.\r\n                <a href=\"https://www.privacy.go.kr/front/wcp/dcl/per/personalInfoFileSrhList.do?searchInsttCode=B500001&searchInsttNm=한국수자원공사\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">☞바로가기</a>\r\n                <ul class=\"imgDis2Li02 ml_20 mr_20 mt_20\">\r\n                    <li class=\"txt mt_0 pr_20\" style=\"width:75%; border-right:1px solid #ddd;\">※ 개인정보포털(www.privacy.go.kr)▶개인서비스▶정보주체권리행사▶개인정보열람등요구▶개인정보파일 목록 검색▶기관명에 “한국수자원공사”를 입력하면 조회가 가능합니다.</li>\r\n                    <li class=\"photo mt_0 pl_20 pt_0\" style=\"width:13%;\">\r\n                        \r\n                        <img id=\"guid_qr_01_202509\" src=\"https://www.riverguide.go.kr/kor/resources/images/content/guid_qr_01_202509.jpg\" alt=\"개인정보포털 개인정보열람등요구, 모바일용 QR코드\" title=\"개인정보포털 개인정보열람등요구, 모바일용 QR코드\" />\r\n                    </li>\r\n                </ul>\r\n            </li>\r\n        </ol>\r\n    </li>\r\n\r\n    <div id=\"step02\">\r\n        <span class=\"hidden\">제2조(개인정보의 처리 및 보유기간)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제2조(개인정보의 처리 및 보유기간)</strong>\r\n        <ol>\r\n            <li>① K-water 물문화관 통합 포털은 법령에 따른 개인정보 보유기간 또는 정보주체로부터 개인정보를 수집 시 동의받은 보유기간 내에서 개인정보를 처리하고 보유합니다.</li>\r\n            <li>② K-water 물문화관 통합 포털에서 처리하는 개인정보의 처리 및 보유기간은 다음과 같습니다. </li>\r\n        </ol>\r\n        <div class=\"scrollTable\">\r\n        <table class=\"basic_board_table\">\r\n            <caption>개인정보 보호법에 따른 개인정보의 처리 및 보유기간을 보여주는 표입니다.</caption>\r\n            <colgroup>\r\n                <col style=\"width: 8%;\">\r\n                <col style=\"width: 46%;\">\r\n                <col style=\"width: 23%;\">\r\n                <col style=\"width: 23%;\">\r\n            </colgroup>\r\n            <thead>\r\n                <tr>\r\n                    <th scope=\"col\">순번</th>\r\n                    <th scope=\"col\">개인정보파일의 명칭</th>\r\n                    <th scope=\"col\">처리근거</th>\r\n                    <th scope=\"col\">보유기간</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <th scope=\"row\">1</th>\r\n                    <td>K-water 물문화관 통합 포털 자전거 종주인증 신청정보</td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>정보주체의 동의</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>2년</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">2</th>\r\n                    <td>K-water 물문화관 통합 포털 종주인증 수첩 및 기념품 구매정보</td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>정보주체의 동의</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>발송일로부터 30일</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">3</th>\r\n                    <td>K-water 물문화관 통합 포털 회원정보</td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>정보주체의 동의</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>2년</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n            </tbody>\r\n        </table>\r\n        </div>\r\n    </li>\r\n\r\n    <div id=\"step03\">\r\n        <span class=\"hidden\">제3조(처리하는 개인정보 항목)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제3조(처리하는 개인정보 항목)</strong>\r\n        <ol>\r\n            <li>① K-water 물문화관 통합 포털은 소관업무 및 법령에서 정한 최소한의 개인정보만을 처리ㆍ보유하고 있습니다.</li>\r\n        </ol>\r\n        <ol>\r\n            <li>② K-water 물문화관 통합 포털은 다음과 같은 개인정보를 「개인정보 보호법」 제15조제1항제1호에 따라 정보주체의 동의를 받아 처리하고 있습니다.</li>\r\n        </ol>\r\n        <div class=\"scrollTable\">\r\n        <table class=\"basic_board_table\">\r\n            <caption>개인정보 보호법에 따른 처리하는 개인정보 항목을 보여주는 표입니다.</caption>\r\n            <colgroup>\r\n                <col style=\"width: 8%;\">\r\n                <col style=\"width: 34%;\">\r\n                <col style=\"width: 26%;\">\r\n                <col style=\"width: 32%;\">\r\n            </colgroup>\r\n            <thead>\r\n                <tr>\r\n                    <th scope=\"col\">순번</th>\r\n                    <th scope=\"col\">개인정보파일의 명칭</th>\r\n                    <th scope=\"col\">처리목적</th>\r\n                    <th scope=\"col\">처리항목</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <th scope=\"row\">1</th>\r\n                    <td>K-water 물문화관 통합 포털 자전거 종주인증 신청정보</td>\r\n                    <td>자전거 종주인증 내역관리</td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>(필수) 이름, 집주소, 핸드폰, 이메일</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">2</th>\r\n                    <td>K-water 물문화관 통합 포털 자전거 종주인증 수첩 및 기념품 구매정보</td>\r\n                    <td>종주인증 수첩 및 기념품(메달, 케이스, 인증서 등) 제작 및 배송</td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>(필수) 이름, 집주소, 집연락처, 핸드폰</li>\r\n                            <li>(선택) 이메일</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">3</th>\r\n                    <td>K-water 물문화관 통합 포털 회원정보</td>\r\n                    <td>4대강 주변시설 예약 및 자전거 종주인증 관리</td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>(필수) 이름, 아이디, 비밀번호, 이메일, 핸드폰, IP, CI, DI</li>\r\n                            <li>(선택) 집주소, 종주인증수첩번호, 집연락처</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n            </tbody>\r\n        </table>\r\n        </div>\r\n\r\n        <div class=\"item_desc_box\">\r\n            <h2 style=\"padding-top:20px;padding-bottom:20px;\">처리하는 개인정보 항목에 대한 추가 설명</h2>\r\n            <ol class=\"ol01\">\r\n                <li>1. 동의를 받는 경우와 받지 않는 경우의 차이\r\n                    <ol class=\"ol02\">\r\n                        <li>- 정보주체의 자기결정권 보장을 위하여 개인정보 수집·이용 동의서(온/오프라인)를 통해 동의를 받아 개인정보를 처리합니다.</li>\r\n                        <li>- 다만, 법률에 특별한 규정이 있거나 법령상 의무를 준수하기 위해 불가피한 경우, 공공기관으로서 법령 등에서 정하는 소관 업무의 수행을 위하여 불가피한 경우, 정보주체와의 계약의 체결 및 이행을 위하여 불가피하게 필요한 경우 등에는 정보주체의 동의없이 개인정보를 수집합니다. 이 경우에는 정보주체에게 개인정보 수집 시 수집하는 근거 등을\r\n                            안내하고, 본 개인정보 처리방침을 통해 고지하고 있습니다.</li>\r\n                    </ol>\r\n                </li>\r\n                <li>2. ‘필수’항목과 ‘선택’항목의 차이\r\n                    <ol class=\"ol02\">\r\n                        <li>- ‘필수’항목이란 서비스의 본질적 기능을 제공하기 위해 반드시 필요한 최소한의 개인정보를 의미합니다. 이 정보가 없으면 서비스 가입이나 정상적인 이용이 불가능합니다.</li>\r\n                        <li>- ‘선택’항목이란 서비스의 핵심 기능을 이용하는 데에는 필수적이지 않지만, 정보주체에게 더 나은 혜택이나 부가적인 서비스를 제공하기 위해 추가로 수집하는 정보입니다. 선택항목을 입력하지 않아도 회원 가입이나 서비스 이용에는 제한이 없습니다.</li>\r\n                    </ol>\r\n                </li>\r\n            </ol>\r\n        </div>\r\n        <ol>\r\n            <li>\r\n                ③ 인터넷 서비스 이용과정에서 아래 개인정보 항목이 자동으로 생성되어 수집될 수 있습니다.<br>\r\n                <ol>\r\n                    - IP주소, 쿠키, MAC주소, 서비스 이용기록, 방문기록, 불량 이용기록 등<br>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n    </li>\r\n\r\n<div id=\"step04\">\r\n        <span class=\"hidden\">제4조 (만14세 미만 아동의 개인정보 처리)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제4조 (만14세 미만 아동의 개인정보 처리)</strong>\r\n        <ol>\r\n            <li>\r\n                ① K-water 물문화관 통합 포털은 만 14세 미만 아동으로부터 개인정보를 수집할 경우, 보호법 제22조의2에 따라 법정대리인의 동의를 받습니다. 법정대리인의 동의를 받기 위하여 법정대리인의 성명, 관계, 휴대전화번호를 해당 아동으로부터 수집할 수 있습니다.\r\n            </li>\r\n            <li>\r\n                ② K-water 물문화관 통합 포털은 아래의 적법한 방법으로 법정대리인의 동의를 받습니다.\r\n                <ol>\r\n                    <li>1. 동의 내용을 게재한 인터넷 사이트에 법정대리인이 동의 여부를 표시하도록 하고 개인정보처리자가 그 동의 표시를 확인했음을 법정대리인의 휴대전화 문자 메시지로 알리는 방법</li>\r\n                    <li>2. 동의 내용을 게재한 인터넷 사이트에 법정대리인이 동의 여부를 표시하도록 하고 법정대리인의 신용카드·직불카드 등의 카드정보를 제공받는 방법</li>\r\n                    <li>3. 동의 내용을 게재한 인터넷 사이트에 법정대리인이 동의 여부를 표시하도록 하고 법정대리인의 휴대전화 본인인증 등을 통해 본인 여부를 확인하는 방법</li>\r\n                    <li>4. 동의 내용이 적힌 서면을 법정대리인에게 직접 발급하거나, 우편 또는 팩스를 통하여 전달하고 법정대리인이 동의 내용에 대하여 서명날인 후 제출하도록 하는 방법</li>\r\n                    <li>5. 동의 내용이 적힌 전자우편을 발송하여 법정대리인으로부터 동의의 의사표시가 적힌 전자우편을 전송받는 방법</li>\r\n                    <li>6. 전화를 통하여 동의 내용을 법정대리인에게 알리고 동의를 얻거나 인터넷주소 등 동의 내용을 확인할 수 있는 방법을 안내하고 재차 전화 통화를 통하여 동의를 얻는 방법</li>\r\n                    <li>7. 그 밖에 위와 준하는 방법으로 법정대리인에게 동의 내용을 알리고 동의의 의사표시를 확인하는 방법</li>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n    </li>\r\n\r\n    <div id=\"step05\">\r\n        <span class=\"hidden\">제5조 (개인정보의 제3자 제공에 관한 사항)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제5조 (개인정보의 제3자 제공에 관한 사항)</strong>\r\n        <ol>\r\n            <li>\r\n                K-water 물문화관 통합 포털은 보호법 제17조 및 제18조에 따라 원칙적으로 정보주체의 개인정보를 수집ㆍ이용 목적으로 명시한 범위 내에서 처리하며, 다음의 경우를 제외하고는 정보주체의 사전 동의 없이 목적 범위를 초과하여 처리하거나 제3자에게 제공하지 않습니다.\r\n                <ol>\r\n                    <li>1. 정보주체로부터 별도의 동의를 받는 경우</li>\r\n                    <li>2. 다른 법률에 특별한 규정이 있는 경우</li>\r\n                    <li>3. 명백히 정보주체 또는 제3자의 급박한 생명, 신체, 재산의 이익을 위하여 필요하다고 인정되는 경우</li>\r\n                    <li>4. 개인정보를 목적 외의 용도로 이용하거나 이를 제3자에게 제공하지 아니하면 다른 법률에서 정하는 소관업무를 수행할 수 없는 경우로서 보호위원회의 심의ㆍ의결을 거친 경우</li>\r\n                    <li>5. 조약, 그 밖의 국제협정의 이행을 위하여 외국정부 또는 국제기구에 제공하기 위하여 필요한 경우</li>\r\n                    <li>6. 범죄의 수사와 공소의 제기 및 유지를 위하여 필요한 경우</li>\r\n                    <li>7. 법원의 재판업무 수행을 위하여 필요한 경우</li>\r\n                    <li>8. 형 및 감호, 보호처분의 집행을 위하여 필요한 경우</li>\r\n                    <li>9. 공중위생 등 공공의 안전과 안녕을 위하여 긴급히 필요한 경우</li>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n    </li>\r\n\r\n    <div id=\"step06\">\r\n        <span class=\"hidden\">제6조 (개인정보처리의 위탁에 관한 사항)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제6조 (개인정보처리의 위탁에 관한 사항)</strong>\r\n        <ol>\r\n            <li>① K-water 물문화관 통합 포털은 원활한 업무처리를 위하여 보호법 제26조에 따라 다음과 같이 개인정보 처리업무를 위탁하고 있습니다.</li>\r\n            <li><strong><a href=\"https://www.kwater.or.kr/gov3/sub03/annoList.do?seq=308&amp;s_mid=1664&amp;cate1=7&amp;x=0&amp;y=0\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">☞  K-water 개인정보처리 위탁 현황 확인하기</a></strong>\r\n                <ol>\r\n                    <li>※ K-water홈페이지(kwater.or.kr) ▷ 국민소통 ▷ 정보공개 ▷ 사전정보공표 ▷ 사규,정보화 ▷ 개인정보처리 위탁 현황에서 확인할 수 있습니다.</li>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n        <div class=\"scrollTable\">\r\n        <table class=\"basic_board_table\">\r\n            <caption>개인정보 보호법에 따른 개인정보처리의 위탁에 관한 사항을 보여주는 표입니다.</caption>\r\n            <colgroup>\r\n                <col style=\"width: 8%;\">\r\n                <col style=\"width: 18%;\">\r\n                <col style=\"width: 37%;\">\r\n                <col style=\"width: 37%;\">\r\n            </colgroup>\r\n            <thead>\r\n                <tr>\r\n                    <th scope=\"col\">순번</th>\r\n                    <th scope=\"col\">담당부서(소속)</th>\r\n                    <th scope=\"col\">위탁받는자(수탁자)</th>\r\n                    <th scope=\"col\">위탁 업무의 내용</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <th scope=\"row\">1</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>경영혁신실</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>ㆍ 업체명: 케이워터운영관리㈜ </li>\r\n                            <li>ㆍ 전화: 042-636-9950</li>\r\n                        </ol>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>K-water 고객센터 위탁운영</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">2</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>디지털관리처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>ㆍ 업체명: 아이티센엔텍 컨소시엄<br>&nbsp;&nbsp;&nbsp;&nbsp;(이노솔루텍,인크루넷, 유플러스아이티, 대신네트웍스)</li>\r\n                            <li>ㆍ 전화: 070-4113-6895</li>\r\n                        </ol>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>정보시스템 통합운영 및 유지관리</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">3</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>디지털관리처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>ㆍ 업체명: 나이스평가정보 </li>\r\n                            <li>ㆍ 전화: 02-2121-4553</li>\r\n                        </ol>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>정보시스템 본인인증 서비스</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">4</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>수자원기획처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>ㆍ 업체명: 케이워터운영관리㈜ </li>\r\n                            <li>ㆍ 전화: 031-999-7812</li>\r\n                        </ol>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>강문화관 운영관리 위수탁 협약</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">4-1</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>(재위탁)</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>ㆍ 업체명: 케이에스물류 </li>\r\n                            <li>ㆍ 전화: 042-471-7420</li>\r\n                        </ol>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>종주인증수첩 및 메달 주문 배송</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">4-2</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>(재위탁)</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>ㆍ 업체명: 에스디워크 동행 </li>\r\n                            <li>ㆍ 전화: 031-949-4565</li>\r\n                        </ol>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>종주인증수첩 및 메달 각인</li>\r\n                        </ul>\r\n                    </td>\r\n                </tr>\r\n            </tbody>\r\n        </table>\r\n        </div>\r\n\r\n        <ol>\r\n            <li>\r\n                ② K-water 물문화관 통합 포털은 개인정보의 처리업무 위탁계약 체결 시, 다음 각 호의 내용이 포함되도록 계약서 등 문서로 명시하고 있으며, 이행여부를 정기적으로 관리·감독·교육하고 있습니다.\r\n                <ol>\r\n                    <li>1. 위탁업무 수행 목적 외 개인정보의 처리 금지에 관한 사항</li>\r\n                    <li>2. 개인정보의 기술적·관리적 보호조치에 관한 사항 </li>\r\n                    <li>3. 위탁업무의 목적 및 범위</li>\r\n                    <li>4. 재위탁 제한에 관한 사항</li>\r\n                    <li>5. 개인정보의 관리 현황 점검 및 수탁자 소속직원의 교육에 관한 사항</li>\r\n                    <li>6. 수탁자 의무 위반 시 손해배상 등 책임에 관한 사항</li>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n        <div class=\"river_road\">\r\n            <img id=\"river_road_06_202509\" src=\"https://www.riverguide.go.kr/contentsFileDown.do?file_idx=418\" alt=\"개인정보 처리의 위탁 절차\" title=\"개인정보 처리의 위탁 절차\" />\r\n        </div>\r\n    </li>\r\n\r\n    <div id=\"step07\">\r\n        <span class=\"hidden\">제7조 (정보주체와 법정대리인의 권리·의무 및 그 행사방법에 관한 사항)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제7조 (정보주체와 법정대리인의 권리·의무 및 그 행사방법에 관한 사항)</strong>\r\n        <ol>\r\n            <li>\r\n                ① 정보주체는 보호법에 따라 다음과 같은 권리를 행사할 수 있습니다.\r\n                <ol>\r\n                    <li>1. 개인정보의 열람 요구</li>\r\n                    <li>2. 개인정보의 정정·삭제 요구</li>\r\n                    <li>3. 개인정보의 처리정지 요구</li>\r\n                    <li>4. 개인정보 수집·이용의 동의 철회 요구</li>\r\n                    <li>5. 개인정보의 자동화된 결정 거부·설명 등 요구</li>\r\n                    <li>6. 개인정보의 본인전송 요구</li>\r\n                </ol>\r\n            </li>\r\n            <li>\r\n                ② K-water 물문화관 통합 포털에서 보유하고 있는 개인정보는 보호법 제35조에 따라 열람을 요구할 수 있으며, 다음의 경우에는 열람을 제한하거나 거절할 수 있습니다.\r\n                <ol>\r\n                    <li>1. 법률에 따라 열람이 금지되거나 제한되는 경우</li>\r\n                    <li>2. 다른 사람의 생명ㆍ신체를 해할 우려가 있거나 다른 사람의 재산과 그 밖의 이익을 부당하게 침해할 우려가 있는 경우</li>\r\n                    <li>\r\n                        3. 공공기관이 다음 각 목의 어느 하나에 해당하는 업무를 수행할 때 중대한 지장을 초래하는 경우\r\n                        <ol>\r\n                            <li>가. 조세의 부과ㆍ징수 또는 환급에 관한 업무</li>\r\n                            <li>나. 「초ㆍ중등교육법」 및 「고등교육법」에 따른 각급 학교, 「평생교육법」에 따른 평생교육시설, 그 밖의 다른 법률에 따라 설치된 고등교육기관에서의 성적 평가 또는 입학자 선발에 관한 업무</li>\r\n                            <li>다. 학력ㆍ기능 및 채용에 관한 시험, 자격 심사에 관한 업무</li>\r\n                            <li>라. 보상금ㆍ급부금 산정 등에 대하여 진행 중인 평가 또는 판단에 관한 업무</li>\r\n                            <li>마. 다른 법률에 따라 진행 중인 감사 및 조사에 관한 업무</li>\r\n                        </ol>\r\n                    </li>\r\n                </ol>\r\n            </li>\r\n            <li>③ K-water 물문화관 통합 포털에서 보유하고 있는 개인정보는 보호법 제36조에 따라 정정ㆍ삭제를 요구할 수 있습니다. 다만, 다른 법령에서 그 개인정보가 수집 대상으로 명시되어 있는 경우에는 그 삭제를 요구할 수 없습니다.</li>\r\n            <li>④ K-water 물문화관 통합 포털에서 보유하고 있는 개인정보는 보호법 제37조에 따라 처리정지를 요구할 수 있으며, 다음의 경우에는 처리정지 요구를 거절할 수 있습니다.\r\n                <ol>\r\n                    <li>1. 법률에 특별한 규정이 있거나 법령상 의무를 준수하기 위하여 불가피한 경우</li>\r\n                    <li>2. 다른 사람의 생명ㆍ신체를 해할 우려가 있거나 다른 사람의 재산과 그 밖의 이익을 부당하게 침해할 우려가 있는 경우</li>\r\n                    <li>3. 공공기관이 개인정보를 처리하지 아니하면 다른 법률에서 정하는 소관 업무를 수행할 수 없는 경우</li>\r\n                    <li>4. 개인정보를 처리하지 아니하면 정보주체와 약정한 서비스를 제공하지 못하는 등 계약의 이행이 곤란한 경우로서 정보주체가 그 계약의 해지 의사를 명확하게 밝히지 아니한 경우</li>\r\n                </ol>\r\n            </li>\r\n            <li>⑤ K-water 물문화관 통합 포털에서 보유하고 있는 개인정보는 보호법 제37조의2에 따라 자동화된 결정에 대한 거부·설명·검토를 요구할 수 있으며, 다른 사람의 생명·신체·재산과 그 밖의 이익을 부당하게 침해할 우려가 있는 등 정당한 사유가 있는 경우에는 거부·설명·검토 요구에 대해 거절할 수 있습니다.\r\n            </li>\r\n            <li>⑥ K-water 물문화관 통합 포털에서 보유하고 있는 개인정보는 개인정보 보호법 제35조의2에 따라 본인전송요구를 할 수 있으며 컴퓨터 등 정보처리 가능한 형태(PDF, CSV, XLS 등)로 정보주체 본인만이 접근가능한 전송경로(본인 명의의 이동통신단말장치 또는 전자우편 계정 등)으로 전송을 요구할 수 있습니다.\r\n            </li>\r\n            <li>⑦ 제1항에 따른 권리행사는 개인정보보호위원회 별지 제1호 서식에 따른 개인정보(열람, 정정·삭제, 처리정지, 동의철회, 자동화된 결정 거부·설명, 본인전송요구 등) 요구서를 작성 후 서면·전자우편·모사전송(FAX) 등을 통하여 요구할 수 있으며, 이에 대해 지체 없이 조치하겠습니다. K-water 물문화관 통합 포털은 요구를 받은 날부터 10일 이내에 조치하도록 하겠습니다.\r\n            </li>\r\n            <li>⑧ 정보주체가 개인정보의 오류 등에 대한 정정 또는 삭제를 요구한 경우에는 정정 또는 삭제를 완료할 때까지 해당 개인정보를 이용하거나 제공하지 않습니다.</li>\r\n            <li>⑨ 제1항에 따른 권리행사는 정보주체의 법정대리인이나 위임을 받은 자 등 대리인을 통하여 할 수 있습니다. 이 경우 별지 제2호 서식에 따른 위임장을 제출하셔야 합니다.</li>\r\n            <li>⑩ 정보주체 권리에 따른 요구, 정정·삭제의 요구, 처리정지, 동의철회, 자동화된 결정 거부·설명, 본인전송요구 등 요구 시 열람 등 요구를 한 자가 본인이거나 정당한 대리인인지를 확인합니다.</li>\r\n            <li>⑪ 이의제기 절차 및 방법은 다음과 같습니다.\r\n                <ol>\r\n                    <li>1. 정보주체는 개인정보 열람, 정정·삭제, 처리정지, 동의철회, 자동화된 결정 거부·설명, 본인전송요구 등에 대한 조치에 불만이 있거나 이의가 있을 경우에는 이의신청서를 작성하여 개인정보 보호담당자에게 이의제기를 할 수 있습니다.\r\n                    </li>\r\n                    <li>2. K-water 물문화관 통합 포털은 이의제기를 받은 날로부터 10일 이내에 이의제기 내용을 검토 한 후, 그 결과에 따라 조치하고 개인정보(열람, 정정, 삭제, 처리정지·동의철회)요구에 대한 결과 통지서에 따라 정보주체에게 안내드립니다.\r\n                    </li>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n\r\n        <div class=\"down_01\">\r\n            <strong>\r\n                <a href=\"https://www.riverguide.go.kr/template/privacyTemplate1_202509.hwp\" download=\"[별지 제1호 서식] 개인정보 (열람, 정정·삭제, 처리정지, 동의철회, 자동화된 결정 거부·설명, 본인전송요구 등) 요구서.hwp\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n                   [별지 제1호 서식] 개인정보 (열람, 정정·삭제, 처리정지, 동의철회, 자동화된 결정 거부·설명, 본인전송요구 등) 요구서\r\n                    <span class=\"hidden\">다운로드</span>\r\n                </a>\r\n            </strong>\r\n        </div>\r\n        <div class=\"down_01\">\r\n            <strong>\r\n                <a href=\"https://www.riverguide.go.kr/template/privacyTemplate2_202509.hwp\" download=\"[별지 제2호 서식] 위임장.hwp\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n                    [별지 제2호 서식] 위임장\r\n                    <span class=\"hidden\">다운로드</span>\r\n                </a>\r\n            </strong>\r\n        </div>\r\n        <div class=\"down_01\">\r\n            <strong>\r\n                <a href=\"https://www.riverguide.go.kr/template/privacyTemplate3_202509.hwp\" download=\"[별지 제3호 서식] 개인정보 열람 등 조치에 대한 이의신청서.hwp\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n                    [별지 제3호 서식] 개인정보 열람 등 조치에 대한 이의신청서\r\n                    <span class=\"hidden\">다운로드</span>\r\n                </a>\r\n            </strong>\r\n        </div>\r\n\r\n    </li>\r\n    <div class=\"river_road\">\r\n        <img id=\"river_road_01\" src=\"https://www.riverguide.go.kr/contentsFileDown.do?file_idx=419\" alt=\"개인정보 열람등 요구 방법\" title=\"개인정보 열람등 요구 방법\" />\r\n    </div>\r\n\r\n    <div id=\"step08\">\r\n        <span class=\"hidden\">제8조 (개인정보 파기절차 및 방법)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제8조 (개인정보 파기절차 및 방법)</strong>\r\n        <ol>\r\n            <li>① K-water 물문화관 통합 포털은 원칙적으로 개인정보 보유기간의 경과, 개인정보의 처리 목적 달성, 가명정보의 처리기간 경과 등 그 개인정보가 불필요하게 되었을때에는 지체없이 해당 개인정보를 파기합니다.</li>\r\n            <li>② 제1항의 경우에도 불구하고 다른 법령에 따라 개인정보를 계속 보존하여야 하는 경우에는, 해당 개인정보(또는 개인정보파일)을 별도의 데이터베이스(DB)로 옮기거나 보관 장소를 달리하여 보존합니다.</li>\r\n            <li>\r\n                ③ 개인정보 파기의 절차 및 방법은 다음과 같습니다.\r\n                <ol>\r\n                    <li>\r\n                        1. 파기절차\r\n                        <ol>\r\n                            <li>K-water 물문화관 통합 포털은 파기하여야 하는 개인정보(또는 개인정보파일)에 대해 개인정보 파기계획을 수립하여 파기합니다. K-water 물문화관 통합 포털은 파기 사유가 발생한 개인정보(또는 개인정보파일)을 선정하고, 개인정보 보호책임자의 승인을 받아 개인정보(또는 개인정보파일)을 파기합니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>\r\n                        2. 파기방법\r\n                        <ol>\r\n                            <li>가. 전자적 파일 형태인 경우: 복원이 불가능한 방법으로 영구 삭제</li>\r\n                            <li>나. 기록물, 인쇄물, 서면, 그 밖의 기록매체인 경우: 파쇄 또는 소각</li>\r\n                        </ol>\r\n                    </li>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n    </li>\r\n    <div class=\"river_road\">\r\n        <img id=\"river_road_08_202509\" src=\"https://www.riverguide.go.kr/contentsFileDown.do?file_idx=420\" alt=\"개인정보(파일)파기절차\" title=\"개인정보(파일)파기절차\" />\r\n    </div>\r\n\r\n    <div id=\"step09\">\r\n        <span class=\"hidden\">제9조 (개인정보 안전성 확보 조치)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제9조 (개인정보 안전성 확보 조치)</strong>\r\n        <ol>\r\n            <li>\r\n                K-water 물문화관 통합 포털은 보호법 제29조에 따라 개인정보의 안전성 확보를 위해 다음과 같은 조치를 취하고 있습니다.\r\n                <ol>\r\n                    <li>1. 내부관리계획의 수립 및 시행</li>\r\n                    <ol>\r\n                        <li>K-water 물문화관 통합 포털은 개인정보의 안전한 관리를 위하여 내부관리계획을 수립·시행하고 있습니다. 또한 내부관리계획에 따라 연 1회 이상의 자체점검을 실시하고 있습니다.</li>\r\n                    </ol>\r\n                    <li>2. 개인정보 취급직원의 최소화 및 교육\r\n                        <ol>\r\n                            <li>개인정보를 취급하는 직원은 반드시 필요한 인원에 한하여 지정·관리하고 있으며, 업무상 필요한 최소한의 접근 권한만 부여하고 있습니다.</li>\r\n                            <li>또한, 개인정보를 취급하는 직원을 대상으로 안전한 관리를 위한 교육을 실시하고 있습니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>3. 개인정보에 대한 접근 제한\r\n                        <ol>\r\n                            <li>개인정보를 처리하는 개인정보처리시스템에 대한 접근권한의 부여·변경·말소를 통하여 개인정보에 대한 접근통제를 위한 필요한 조치를 하고 있으며, 침입차단시스템을 이용하여 외부로부터의 무단 접근을 통제하고 있습니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>4. 접속기록의 보관\r\n                        <ol>\r\n                            <li>개인정보처리시스템에 접속한 기록을 최소 1년 이상 보관·관리하고 있습니다. 또한 5만명 이상의 정보주체에 관하여 개인정보를 처리하거나, 고유식별정보 또는 민감정보를 처리하는 개인정보처리시스템에 접속한 기록은 2년 이상 보관·관리하고 있습니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>5. 개인정보의 암호화\r\n                        <ol>\r\n                            <li>개인정보는 암호화 등을 통해 안전하게 저장 및 관리되고 있습니다. 또한, 중요한 데이터는 저장 및 전송 시 암호화하여 사용하는 등의 별도 보안기능을 사용하고 있습니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>6. 보안프로그램 설치 및 주기적 점검ㆍ갱신\r\n                        <ol>\r\n                            <li>해킹이나 컴퓨터 바이러스 등에 의한 개인정보 유출 및 훼손을 방지하기 위하여 보안프로그램을 설치하고 주기적으로 갱신·점검하고 있습니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>7. 비인가자에 대한 출입 통제\r\n                        <ol>\r\n                            <li>개인정보를 보관하고 있는 개인정보처리시스템의 물리적 보관 장소를 별도로 두고 이에 대해 출입통제 절차를 수립·운영하고 있습니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>8. 잠금장치 설치 및 반출·입 통제\r\n                        <ol>\r\n                            <li>개인정보가 포함된 서류, 보조저장매체 등은 잠금장치가 있는 안전한 장소에 보관하고, 반출·입 통제에 대한 보안 대책을 마련하고 있습니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n    </li>\r\n    <div class=\"river_road\">\r\n        <img id=\"river_road_09_202509\" src=\"https://www.riverguide.go.kr/contentsFileDown.do?file_idx=421\" alt=\"개인정보 안전성 확보 조치\" title=\"개인정보 안전성 확보 조치\" />\r\n    </div>\r\n\r\n    <div id=\"step10\">\r\n        <span class=\"hidden\">제10조 (개인정보 자동 수집 장치의 설치·운영 및 거부에 관한 사항)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제10조 (개인정보 자동 수집 장치의 설치·운영 및 거부에 관한 사항)</strong>\r\n        <ol>\r\n            <li>① K-water 물문화관 통합 포털은 이용자에게 개별적인 맞춤서비스를 제공하기 위해 이용정보를 저장하고 수시로 불러오는 ‘쿠키(cookie)’를 사용하며, 해당 정보를 목적 외로 이용하거나 제3자에게 제공하지 않습니다.</li>\r\n            <li>② 쿠키는 웹사이트를 운영하는데 이용되는 서버(http)가 이용자의 컴퓨터 브라우저에게 보내는 소량의 정보이며 이용자의 PC 컴퓨터내의 하드디스크에 저장되기도 합니다.\r\n                <ol>\r\n                    <li>가. 쿠키의 사용 목적\r\n                        <ol>\r\n                            <li>이용자가 방문한 각 서비스와 웹 사이트들에 대한 방문 및 이용형태, 인기 검색어, 보안접속 여부, 등을 파악하여 이용자에게 최적화된 정보 제공을 위해 사용됩니다.</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>나. 쿠키의 설치·운영 및 거부: 웹브라우저 옵션 설정을 통해 쿠키 허용, 쿠키 차단 등의 설정을 할 수 있습니다.\r\n                        <ol>\r\n                            <li>- Chrome: 웹브라우저 우측 상단의 설정 메뉴 > 개인정보 및 보안 > 쿠키 및 기타 사이트 데이터</li>\r\n                            <li>- IE: 웹브라우저 우측 상단의 설정 메뉴 > 인터넷옵션 > 개인정보 > 고급</li>\r\n                            <li>- Edge: 웹브라우저 상단의 설정 메뉴 > 업데이트 및 보안 > 쿠키 </li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>다. 쿠키 저장을 거부할 경우 맞춤형 서비스 이용에 어려움이 발생할 수 있습니다.</li>\r\n                </ol>\r\n            </li>\r\n        </ol>\r\n    </li>\r\n    <div class=\"river_road\">\r\n        <img id=\"river_road_10_202509\" src=\"https://www.riverguide.go.kr/contentsFileDown.do?file_idx=422\" alt=\"쿠키 삭제 및 차단 방법\" title=\"쿠키 삭제 및 차단 방법\" />\r\n    </div>\r\n\r\n    <div id=\"step11\">\r\n        <span class=\"hidden\">제11조(민감정보의 공개 가능성 및 비공개 선택)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제11조(민감정보의 공개 가능성 및 비공개 선택)</strong>\r\n        <ol>\r\n            <li>K-water 물문화관 통합 포털은 보호법 제23조제3항에 따라 서비스를 제공하는 과정에서 공개되는 정보에 정보주체의 민감정보가 포함됨으로써 사생활 침해의 위험성이 있다고 판단하는 때에는 서비스의 제공 전에 민감정보의 공개 가능성 및 비공개를 선택하는 방법을 각 시스템의 홈페이지 및 대표홈페이지에 게재하여 정보주체가 확인할 수 있도록 안내하겠습니다.</li>\r\n        </ol>\r\n    </li>\r\n\r\n    <div id=\"step12\">\r\n        <span class=\"hidden\">제12조 (개인정보 보호책임자 및 담당자)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제12조 (개인정보 보호책임자 및 담당자)</strong>\r\n        <ol>\r\n            <li>①K-water 물문화관 통합 포털은 보호법 제31조에 따라 개인정보를 보호하고 개인정보처리와 관련한 정보주체의 불만 처리 및 피해구제 등을 위하여 아래와 같이 개인정보 보호책임자 및 담당자를 지정하고 있습니다.</li>\r\n        </ol>\r\n        <div class=\"scrollTable\">\r\n        <table class=\"basic_board_table\">\r\n            <caption>개인정보 보호책임자 및 담당자 연락처 정보를 보여주는 표입니다.</caption>\r\n            <colgroup>\r\n                <col style=\"width: 24%;\">\r\n                <col style=\"width: 18%;\">\r\n                <col style=\"width: 16%;\">\r\n                <col style=\"width: 42%;\">\r\n            </colgroup>\r\n            <thead>\r\n                <tr>\r\n                    <th scope=\"col\">구분</th>\r\n                    <th scope=\"col\">부서명</th>\r\n                    <th scope=\"col\">성명</th>\r\n                    <th scope=\"col\">연락처</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <th scope=\"row\">개인정보 보호책임자</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>정보보안처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>김학성</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>전화 : 042-629-3080</li>\r\n                            <li>팩스 : 042-629-4982</li>\r\n                            <li>메일 : NPIKHS@KWATER.OR.KR</li>\r\n                        </ol>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">개인정보 보호분야별 책임자</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>수자원기획처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>배영대</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>전화 : 042-629-3100</li>\r\n                            <li>팩스 : 042-629-4813</li>\r\n                            <li>메일 : SKD99@KWATER.OR.KR</li>\r\n                        </ol>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">개인정보 보호담당자</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>정보보안처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>박종웅</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>전화 : 042-629-3097</li>\r\n                            <li>팩스 : 042-629-4982</li>\r\n                            <li>메일 : PJU@KWATER.OR.KR</li>\r\n                        </ol>\r\n                    </td>\r\n                </tr>\r\n            </tbody>\r\n        </table>\r\n        </div>\r\n\r\n        <ol>\r\n            <li>② 정보주체는 K-water 물문화관 통합 포털의 서비스(또는 사업)을 이용하시면서 발생한 모든 개인정보 보호 관련 문의, 불만 처리, 피해구제 등에 관한 사항을 개인정보 보호책임자 및 담당자로 문의하실 수 있습니다. K-water 물문화관 통합 포털은 정보주체의 문의에 대해 지체없이 답변 및 처리해 드릴 것입니다.</li>\r\n        </ol>\r\n    </li>\r\n\r\n    <div id=\"step13\">\r\n        <span class=\"hidden\">제13조 (개인정보의 열람청구를 접수·처리하는 부서)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제13조 (개인정보의 열람청구를 접수·처리하는 부서)</strong>\r\n        <ol>\r\n            <li>① 정보주체는 제6조에서 규정하고 있는 권리를 아래의 부서에 청구할 수 있습니다. K-water 물문화관 통합 포털은 정보주체의 개인정보 열람청구가 신속하게 처리되도록 노력하겠습니다.</li>\r\n        </ol>\r\n\r\n        <div class=\"scrollTable\">\r\n        <table class=\"basic_board_table\">\r\n            <caption>개인정보 열람청구 담당자의 연락처 정보를 보여주는 표입니다.</caption>\r\n            <colgroup>\r\n                <col style=\"width: 8%;\">\r\n                <col style=\"width: 36%;\">\r\n                <col style=\"width: 18%;\">\r\n                <col style=\"width: 38%;\">\r\n            </colgroup>\r\n            <thead>\r\n                <tr>\r\n                    <th scope=\"col\">순번</th>\r\n                    <th scope=\"col\">개인정보파일의 명칭</th>\r\n                    <th scope=\"col\">부서명</th>\r\n                    <th scope=\"col\">연락처</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <th scope=\"row\">1</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>K-water 물문화관 통합 포털 자전거 종주인증 신청정보</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>수자원기획처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>전화 : 042-629-3148</li>\r\n                            <li>팩스 : 042-629-4813</li>\r\n                            <li>메일 : YOUME@KWATER.OR.KR</li>\r\n                        </ol>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">2</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>K-water 물문화관 통합 포털 종주인증 수첩 및 기념품 구매정보</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>수자원기획처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>전화 : 042-629-3148</li>\r\n                            <li>팩스 : 042-629-4813</li>\r\n                            <li>메일 : YOUME@KWATER.OR.KR</li>\r\n                        </ol>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <th scope=\"row\">3</th>\r\n                    <td>\r\n                        <ul>\r\n                            <li>K-water 물문화관 통합 포털 회원정보</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ul>\r\n                            <li>수자원기획처</li>\r\n                        </ul>\r\n                    </td>\r\n                    <td>\r\n                        <ol>\r\n                            <li>전화 : 042-629-3148</li>\r\n                            <li>팩스 : 042-629-4813</li>\r\n                            <li>메일 : YOUME@KWATER.OR.KR</li>\r\n                        </ol>\r\n                    </td>\r\n                </tr>\r\n            </tbody>\r\n        </table>\r\n        </div>\r\n        <ol>\r\n            <li>② 정보주체는 제1항의 열람청구 접수·처리부서 이외에, 개인정보보호위원회 개인정보포털을 통해 개인정보 열람청구를 할 수 있습니다.\r\n                <a href=\"https://www.privacy.go.kr/front/wcp/dcl/per/persnalInfoAgree.do\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">☞바로가기</a>\r\n                <ul class=\"imgDis2Li02 ml_20 mr_20 mt_20\">\r\n                    <li class=\"txt mt_0 pr_20\" style=\"width:75%; border-right:1px solid #ddd;\">※ 개인정보포털(www.privacy.go.kr) ▶ 개인서비스 ▶ 정보주체권리행사 ▶ 개인정보열람등요구에서 청구 가능(본인인증 필요)</li>\r\n                    <li class=\"photo mt_0 pl_20 pt_0\" style=\"width:13%;\">\r\n                        \r\n                        <img id=\"guid_qr_02_202509\" src=\"https://www.riverguide.go.kr/kor/resources/images/content/guid_qr_02_202509.jpg\" alt=\"개인정보포털 열람요구 위탁 모바일용 QR코드\" title=\"개인정보포털 열람요구 위탁 모바일용 QR코드\" />\r\n                    </li>\r\n                </ul>\r\n            </li>\r\n            <li>③ 정보주체는 한국수자원공사 및 관련사이트 이외에, 개인정보보호위원회 개인정보 포털을 통해 회원탈퇴 서비스를 이용 할 수 있습니다.\r\n                <a href=\"https://www.privacy.go.kr/front/contents/cntntsView.do?contsNo=192\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">☞바로가기</a>\r\n                <ul class=\"imgDis2Li02 ml_20 mr_20 mt_20\">\r\n                    <li class=\"txt mt_0 pr_20\" style=\"width:75%; border-right:1px solid #ddd;\">※ 개인정보포털(www.privacy.go.kr) ▶ 개인서비스 ▶ 정보주체권리행사 ▶ 웹사이트 회원탈퇴에서 탈퇴 가능(본인인증 필요)</li>\r\n                    <li class=\"photo mt_0 pl_20 pt_0\" style=\"width:13%;\">\r\n                        \r\n                        <img id=\"guid_qr_03_202509\" src=\"https://www.riverguide.go.kr/kor/resources/images/content/guid_qr_03_202509.jpg\" alt=\"개인정보포털 탈퇴신청 지원 모바일용 QR코드\" title=\"개인정보포털 탈퇴신청 지원 모바일용 QR코드\" />\r\n                    </li>\r\n                </ul>\r\n            </li>\r\n        </ol>\r\n    </li>\r\n\r\n    <div id=\"step14\">\r\n        <span class=\"hidden\">제14조(권익침해 구제방법)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제14조(권익침해 구제방법)</strong>\r\n        <ol>\r\n            <li>정보주체는 다음 각 호의 기관에 개인정보 침해에 대한 피해구제, 상담 등을 문의할 수 있습니다. K-water 물문화관 통합 포털의 자체적인 개인정보 불만처리, 피해구제 결과에 만족하지 못하거나 보다 자세한 도움이 필요한 경우 아래의 기관으로 문의하여 주시기 바랍니다.\r\n                <ol>\r\n                    <li>1. 개인정보 분쟁조정위원회\r\n                        <ol>\r\n                            <li>소관업무 : 개인정보 분쟁조정신청, 집단분쟁조정 </li>\r\n                            <li>홈페이지 :\r\n                                <a href=\"http://www.kopico.go.kr\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">www.kopico.go.kr </a>\r\n                            </li>\r\n                            <li>전화 : (국번없이)\r\n                                <a href=\"tel:1833-6972\">1833-6972</a>\r\n                            </li>\r\n                            <li>주소 : (03171) 서울특별시 종로구 세종대로 209 정부서울청사 12층</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>2. 개인정보 침해신고센터 (한국인터넷진흥원 운영)\r\n                        <ol>\r\n                            <li>소관업무 : 개인정보 침해사실 신고, 상담 신청 </li>\r\n                            <li>홈페이지 :\r\n                                <a href=\"http://privacy.kisa.or.kr\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">privacy.kisa.or.kr</a>\r\n                            </li>\r\n                            <li>전화 : (국번없이)\r\n                                <a href=\"tel:118\">118</a>\r\n                            </li>\r\n                            <li>주소 : (58324) 전남 나주시 진흥길 9(빛가람동 301-2) 3층 개인정보침해신고센터</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>3. 대검찰청 사이버범죄수사과\r\n                        <ol>\r\n                            <li>홈페이지 :\r\n                                <a href=\"http://www.spo.go.kr\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">www.spo.go.kr</a>\r\n                            </li>\r\n                            <li>전화 : (국번없이)\r\n                                <a href=\"tel:1301\">1301</a>\r\n                            </li>\r\n                            <li>주소 : (06590) 서울특별시 서초구 반포대로 157</li>\r\n                        </ol>\r\n                    </li>\r\n                    <li>4. 경찰청 사이버범죄신고시스템(ECRM)\r\n                        <ol>\r\n                            <li>홈페이지 :\r\n                                <a href=\"https://ecrm.police.go.kr\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\"> https://ecrm.police.go.kr</a>\r\n                            </li>\r\n                            <li>전화 : (국번없이)\r\n                                <a href=\"tel:182\">182</a>\r\n                            </li>\r\n                            <li>주소 : (03739) 서울특별시 서대문구 통일로 97</li>\r\n                        </ol>\r\n                    </li>\r\n                </ol>\r\n            </li>\r\n            <li>또한 개인정보의 열람, 정정·삭제, 처리정지 등에 대한 정보주체의 요구에 대하여 공공기관의 장이 행한 처분 또는 부작위로 인하여 권리 또는 이익을 침해 받은 자는 행정심판법이 정하는 바에 따라 행정심판을 청구할 수 있습니다.</li>\r\n            <li>\r\n                ※ 중앙행정심판위원회 : (국번없이)\r\n                <a href=\"tel:110\">110</a>\r\n                (\r\n                <a href=\"http://www.simpan.go.kr/\" title=\"새창\" target=\"_blank\" rel=\"noopener noreferrer\">www.simpan.go.kr</a>\r\n                )\r\n            </li>\r\n        </ol>\r\n\r\n        <div class=\"river_road\">\r\n            <img id=\"river_road_02\" src=\"https://www.riverguide.go.kr/contentsFileDown.do?file_idx=65\" alt=\"권익침해 청구방법\" title=\"권익침해 청구방법\" />\r\n        </div>\r\n    </li>\r\n\r\n    <div id=\"step15\">\r\n        <span class=\"hidden\">제15조 (개인정보 보호수준 평가 결과)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제15조 (개인정보 보호수준 평가 결과)</strong>\r\n        <ol>\r\n            <li>① 한국수자원공사는 정보주체의 개인정보를 안전하게 관리하기 위해 「개인정보 보호법」제11조에 따라 매년 개인정보보호위원회에서 실시하는 “개인정보 보호수준 평가”를 받고 있습니다.</li>\r\n            <li>② 한국수자원공사는 2025년도 개인정보 보호수준 평가에서 S등급을 획득하여, 7년 연속 최우수 등급을 달성하였습니다.</li>\r\n            <li>※ S : 90점 이상, A : 90점~80점, B : 80점~70점, C : 70점~60점, D : 60점 미만</li>\r\n        </ol>\r\n\r\n\r\n        <div class=\"river_road\">\r\n            <img id=\"river_road_15_202609\" src=\"https://www.riverguide.go.kr/contentsFileDown.do?file_idx=576\" alt=\"개인정보 보호수준 평가 결과\" title=\"개인정보 보호수준 평가 결과\" />\r\n        </div>\r\n    </li>\r\n\r\n    <div id=\"step16\">\r\n        <span class=\"hidden\">제16조 (개인정보 처리방침 변경)</span>\r\n    </div>\r\n    <li>\r\n        <strong>제16조 (개인정보 처리방침 변경)</strong>\r\n        <ol>\r\n            <li>\r\n                이 개인정보 처리방침은 2026. 9. 1.부터 적용됩니다. 이전의 개인정보 처리방침은 홈페이지 하단의\r\n                <b>“개인정보 처리방침 이력보기”</b>\r\n                에서 확인할 수 있습니다.\r\n            </li>\r\n        </ol>\r\n\r\n        \r\n        <div class=\"scrollTable\">\r\n            <table class=\"basic_board_table\">\r\n                <caption>개인정보 처리방침 변경에 따른 방침을 보여주는 표입니다.</caption>\r\n                <colgroup>\r\n                    <col style=\"width: 12%;\">\r\n                    <col style=\"width: 44%;\">\r\n                    <col style=\"width: 44%;\">\r\n                </colgroup>\r\n                <thead>\r\n                    <tr>\r\n                        <th scope=\"col\">개정조항</th>\r\n                        <th scope=\"col\">주요 개정 내역</th>\r\n                        <th scope=\"col\">변경사유</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <th scope=\"row\">15</th>\r\n                        <td>개인정보 보호수준 평가 결과 연도 수정</td>\r\n                        <td>\r\n                            <ul>\r\n                                <li>2025년 개인정보 보호수준 평가 결과 반영</li>\r\n                            </ul>\r\n                        </td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n        </div>\r\n    </li>\r\n\r\n    <li>\r\n        <strong>\r\n            <a href=\"https://www.riverguide.go.kr/popPolicyOld_20260901.html\" target=\"_blank\" rel=\"noopener noreferrer\" title=\"개인정보 처리방침 이력보기(새창)\">개인정보 처리방침 이력보기</a>\r\n        </strong>\r\n    </li>\r\n</ul>";
